const task = $input.first().json;

if (!task.description) {
  throw new Error("Task description is required");
}

const vloopTask = {
  id: Date.now().toString(),
  timestamp: new Date().toISOString(),
  description: task.description,
  constraints: task.constraints || "",
  status: "running"
};

$workflow.context.data = {
  currentTask: vloopTask,
  startTime: Date.now(),
  iteration: 1,
  max_iterations: 3,
  builderOutputHistory: [],
  judgeResultsHistory: []
};

return vloopTask;

const probing = $input.all()[0].json;
const adversarial = $input.all()[1].json;
const meta = $input.all()[2].json;

const judgeResults = {
  probing: probing.choices[0].message.content,
  adversarial: adversarial.choices[0].message.content,
  meta: meta.choices[0].message.content
};

$workflow.context.data.judgeResults = judgeResults;
$workflow.context.data.judgeResultsHistory.push(judgeResults);

const hasCriticalDefects = judgeResults.adversarial.toLowerCase().includes('critical');

return {
  ...judgeResults,
  requires_remediation: hasCriticalDefects
};

const executionTime = Date.now() - $workflow.context.data.startTime;

const finalResponse = {
  success: !$json.requires_remediation,
  task_id: $workflow.context.data.currentTask.id,
  execution_time: executionTime,
  iterations: $workflow.context.data.iteration,
  results: {
    builderHistory: $workflow.context.data.builderOutputHistory,
    judgeHistory: $workflow.context.data.judgeResultsHistory
  }
};

return finalResponse;

const knowledge = $workflow.context.data.knowledge || [];
let knowledgeContext = 'No prior knowledge found.';
if (knowledge.length > 0) {
  knowledgeContext = 'Prior Knowledge:
' + knowledge.map(k => `- ${k.task}: ${k.solution.substring(0, 100)}...`).join('
');
}

if ($workflow.context.data.iteration > 1) {
  const lastBuilderOutput = $workflow.context.data.builderOutput;
  const judgeFeedback = $workflow.context.data.judgeResults;
  return { 
    builder_prompt: [{ role: 'system', content: 'You are a remediation expert...' }, { role: 'user', content: `Original Task: ${$workflow.context.data.currentTask.description}

${knowledgeContext}

Previous Attempt (Code):
${lastBuilderOutput}

CRITICAL FEEDBACK:
- Probing Judge: ${judgeFeedback.probing}
- Adversarial Judge: ${judgeFeedback.adversarial}

Please generate a new version of the code that addresses all the feedback.` }]
  };
} else {
  return { 
    builder_prompt: [{ role: 'system', content: 'You are an expert software engineer...' }, { role: 'user', content: `Task: ${$json.description}

Constraints: ${$json.constraints}

${knowledgeContext}

Generate implementation:` }]
  };
}

const fs = require('fs');
const filePath = './knowledge_base.json';
let knowledge = [];
try {
  if (fs.existsSync(filePath)) {
    knowledge = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  }
} catch (error) {
  // File might be empty or corrupt, start with empty knowledge
}
$workflow.context.data.knowledge = knowledge;
return $input.first();

const fs = require('fs');
const filePath = './knowledge_base.json';
const newKnowledge = {
  task: $workflow.context.data.currentTask.description,
  solution: $workflow.context.data.builderOutput,
  judges: $workflow.context.data.judgeResults,
  timestamp: new Date().toISOString()
};

const knowledge = $workflow.context.data.knowledge || [];
knowledge.push(newKnowledge);
fs.writeFileSync(filePath, JSON.stringify(knowledge, null, 2));
return $input.first();
